/// Computes the arithmetic series S(n) = 1 + 2 + ... + n for a non‐negative `n`.
/// Assumes that the result is strictly less than 10,000.
pub fn compute_arith_sum(n: u64) -> u64 {
    let mut sum = 0;
    let mut i = 1;
    // Loop from 1 up to n, inclusive.
    while i <= n {
        sum += i;
        i += 1;
    }
    sum
}

